from build import ROOT,LEVELS,prefix,e

CSS='''
*{box-sizing:border-box}body{margin:0;background:#F5EFE5;color:#483C30;font:16px/1.5 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:24px}header{max-width:1000px}h1{font-size:34px;letter-spacing:-1px;line-height:1.15;margin:6px 0 12px}h2{font-size:24px;line-height:1.2;margin:0 0 12px}h3{font-size:18px;margin:20px 0 7px}p{margin:8px 0 14px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.09em;color:#6C7B5D}.intro,.small{color:#786653}.small{font-size:13px}.tabs,.routes,.actions,.links{display:flex;flex-wrap:wrap;gap:8px}.tabs{margin:23px 0 18px}button,a.pill{font:inherit;padding:8px 14px;border:1px solid #D8C8B1;border-radius:24px;background:#FFFCF5;color:#54442F;cursor:pointer;text-decoration:none}button[aria-pressed=true]{background:#5C6D51;color:white;border-color:#5C6D51}button:focus-visible,a:focus-visible{outline:3px solid #427A7C;outline-offset:3px}.rules{background:#EAE5D4;padding:14px 18px;border-radius:12px}.rules strong{color:#496A56}.view[hidden]{display:none}.drawing{overflow:hidden;background:#F9F3E8;border:1px solid #E2D5BE;border-radius:16px}.drawing svg{display:block;width:100%;height:auto}.drawing.enlarged{overflow:auto}.drawing.enlarged svg{min-width:1080px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:22px;align-items:start}.routes{margin-bottom:8px}.routes button{font-size:13px;padding:7px 11px}.route-caption{font-size:13px;color:#786653;min-height:38px}.actions{justify-content:space-between;align-items:center;margin:12px 0 24px}.actions a{font-size:13px}.details p,.details li{font-size:14px}.details ul{padding-left:20px}.details li{margin:6px 0}.metrics{display:flex;gap:18px;margin:15px 0}.metrics b{display:block;font-size:22px;color:#4D6850}.metrics span{font-size:12px;color:#756653}.decision{border-left:3px solid #889D73;padding-left:12px}.overview-notes{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:17px 0 25px}.overview-notes p{font-size:14px}.overview-notes h3{margin:0 0 7px}.assembly{margin:28px 0;padding:20px 0;border-top:1px solid #D6C8B3;border-bottom:1px solid #D6C8B3}.assembly .steps{display:flex;flex-wrap:wrap;align-items:center;gap:12px}.step{flex:1;min-width:180px}.step b{color:#536C51}.step p{font-size:14px}.research{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:26px 0}.research p,.research li{font-size:14px}a{color:#397478}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:11px 8px;border-bottom:1px solid #D9CCB9}td:not(:first-child),th:not(:first-child){text-align:center}footer{margin:28px 0 10px;font-size:13px;color:#786653}.routes label{display:flex;align-items:center;gap:6px;font-size:13px}.routes input{accent-color:#718564}.audit{padding-top:20px;border-top:1px solid #D6C8B3}@media(max-width:1100px){.layout{grid-template-columns:1fr}.details{display:grid;grid-template-columns:1fr 1fr;gap:24px}}@media(max-width:720px){main{padding:16px}h1{font-size:29px}.overview-notes{grid-template-columns:1fr 1fr}.tabs button{font-size:14px}.details,.research{grid-template-columns:1fr;gap:8px}table{font-size:12px}th,td{padding:9px 3px}}@media print{header,.tabs,.rules,.routes,.route-caption,.actions,.details,.assembly,.research,.audit,.links,footer,#overview{display:none!important}.view[hidden]{display:block}.view{break-after:page}.layout{display:block}.drawing{border:0}.drawing svg{max-height:240mm}main{padding:0}body{background:white}}
'''

def article(l):
    i=l['id'];svg=prefix((ROOT/f'level-{i:02d}.svg').read_text(),f'l{i}-')
    food='Salad route' if 'salad' in l['recipes'] else 'Soup route'
    buttons=f'<button data-route="none" aria-pressed="true">Floor plan</button><button data-route="food" aria-pressed="false">{food}</button>'
    if len(l['recipes'])==2:buttons+='<button data-route="soup" aria-pressed="false">Soup route</button>'
    buttons+='<button data-route="wash" aria-pressed="false">Dish loop</button>'
    if l['dash'] or l['throws']:buttons+=f'<label><input type="checkbox" class="skills" checked>Show {"throws + dash" if l["throws"] else "dash"}</label>'
    ingredients=' + '.join(x.title() for x in l['ingredients'])
    recipe='Salad' if l['id']==1 else 'Soup' if l['id']==2 else 'Salad and soup'
    counter_count=sum(s['kind']=='counter' for s in l['stations'])
    return f'''<article class="view" id="level-{i}" hidden><div class="routes" aria-label="Inspect route">{buttons}</div><p class="route-caption" aria-live="polite">All C-numbered surfaces are ordinary counters. The purple target outlines are examples, not special stations.</p>
    <div class="layout"><div><div class="drawing">{svg}</div><div class="actions"><button class="zoom" aria-pressed="false">Enlarge drawing</button><a href="level-{i:02d}.svg" target="_blank" rel="noopener">Open full drawing ↗</a></div></div>
    <aside class="details"><div><div class="eyebrow">LEVEL {i} · {e(l['shape'])}</div><h2>{e(l['title'])}</h2><p>{e(l['headline'])}</p><div class="metrics"><span><b>{counter_count}</b>free counters</span><span><b>{l['dish_pool']}</b>starting dishes</span></div><p><strong>{recipe}</strong><br>{ingredients}</p><p><strong>Learn / use</strong><br>{e(l['skill'])}</p><h3>What the player decides</h3><p class="decision">{e(l['decision'])}</p><p>{e(l['loop'])}</p></div><div><h3>Why this level is different</h3><p>{e(l['changed'])}</p><h3>Useful empty surfaces</h3><ul>{''.join('<li>'+e(x)+'</li>' for x in l['counter_groups'])}</ul><p class="small">These are suggested uses. Every C-numbered counter accepts ingredients, dishes and assembly in exactly the same way.</p><h3>Solo pacing</h3><p>{e(l['fairness'])}</p><p class="small">Up to {l['tickets']} active ticket(s) is an initial tuning proposal. Grid access is checked; fun, timing and physical clearance still need a playable test.</p></div></aside></div></article>'''

overview_svg=prefix((ROOT/'overview.svg').read_text(),'overview-')
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bara Kitchen · Redesigned level plans</title><style>{CSS}</style><main>
<header><div class="eyebrow">BARA KITCHEN · LEVEL REVIEW 02</div><h1>Each kitchen changes how you move food.</h1><p class="intro">Four new layouts with different route structures, flexible worktops and barriers that ingredients can cross.</p></header>
<div class="rules"><strong>One dish. Any empty counter.</strong> Put a clean dish down, add the chopped ingredients, and the meal takes shape. There is no dedicated salad station or separate bowl inventory.</div>
<nav class="tabs" aria-label="Choose a level"><button data-select="overview" aria-pressed="true">Compare all four</button>{''.join(f'<button data-select="level-{l["id"]}" aria-pressed="false">{l["id"]:02d} · {e(l["shape"])}</button>' for l in LEVELS)}</nav>
<section class="view" id="overview"><div class="drawing">{overview_svg}</div><div class="actions"><button class="zoom" aria-pressed="false">Enlarge comparison</button><a href="overview.svg" target="_blank" rel="noopener">Open comparison ↗</a></div><div class="overview-notes">{''.join(f'<div><h3>{l["id"]:02d} · {e(l["title"])}</h3><p>{e(l["decision"])}</p></div>' for l in LEVELS)}</div></section>
{''.join(article(l) for l in LEVELS)}
<section class="assembly"><h2>The counter has no recipe. The dish holds the ingredients.</h2><div class="steps"><div class="step"><b>1 · Choose any free counter</b><p>Place a clean universal serving dish there. Leave other counters free for ingredients or another order.</p></div><div class="step"><b>2 · Add prepared ingredients</b><p>For salad, add chopped tomato and cucumber in either order. You can move a partly assembled dish to another counter.</p></div><div class="step"><b>3 · Serve and reuse</b><p>The same dish also holds cooked soup. One clean-dish rack and one washing loop support both recipes.</p></div></div></section>
<section class="audit"><div class="eyebrow">INGREDIENT CHECK</div><h2>The four existing ingredients still cover every level.</h2><table><thead><tr><th>Ingredient</th><th>Level 1</th><th>Level 2</th><th>Level 3</th><th>Level 4</th></tr></thead><tbody>{''.join('<tr><td>'+k.title()+'</td>'+''.join('<td>'+('Used' if k in l['ingredients'] else '—')+'</td>' for l in LEVELS)+'</tr>' for k in ['tomato','cucumber','carrot','mushroom'])}</tbody></table><p class="small">Whole and chopped concepts exist for all four. The tableware art needs consolidation into one universal dish; low rails are the only new environment family proposed by these plans.</p></section>
<section class="research"><div><h2>What the research changed</h2><p>Phil Duncan describes designing levels around an intended player experience and testing the balance between challenge and frustration. <a href="https://www.gamedeveloper.com/design/road-to-the-igf-ghost-town-games-i-overcooked-i-">Read the developer interview</a>.</p><p>Team17 describes throwing as a way to move ingredients across separated kitchen areas. <a href="https://www.team17.com/news/the-a-z-of-overcooked-2">Read the official guide</a>.</p><p><strong>Our adaptation:</strong> one chef can always walk between work areas. Throws let the player stage food for their next visit. Counter space and the path between tasks create the decisions.</p></div><div><h2>What these drawings prove</h2><p>Every shown working face has a walking route. Each recipe has its required stations. All illustrated throws cross a blocked rail cell into an ordinary counter.</p><p>They do not yet establish character clearance or good pacing. A solo chef still has to visit the far side after throwing, so the benefit comes from staging a small batch, not removing all travel.</p><p><a href="../../LEVEL_DESIGN.md">Full design document and research notes →</a></p></div></section>
<div class="links"><a class="pill" href="README.md">Saved drawings & source</a><a class="pill" href="../kitchen-round-01/">Food & object art</a><button id="print">Print four level plans</button></div>
<footer>Round 02 replaces the first layout proposal. Layouts and revised tableware direction await visual/gameplay validation; no 3D rooms have been built.</footer></main>
<script>
document.querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==b.dataset.select);document.querySelectorAll('[data-select]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}}));
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>{{const panel=b.closest('.view'),svg=panel.querySelector('.plan');svg.classList.remove('show-food','show-soup','show-wash');if(b.dataset.route!=='none')svg.classList.add('show-'+b.dataset.route);panel.querySelectorAll('[data-route]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));panel.querySelector('.route-caption').textContent=b.dataset.route==='none'?'All C-numbered surfaces are ordinary counters. Purple targets are examples, not special stations.':b.dataset.route==='wash'?'Return → wash → the one clean-dish rack. Clean dishes can also go directly to any free counter.':'Example walking route. Repeat pickup/chop for each ingredient. The illustrated assembly counter is one choice; every free counter works.';}}));
document.querySelectorAll('.skills').forEach(c=>c.addEventListener('change',()=>c.closest('.view').querySelector('.plan').classList.toggle('no-skills',!c.checked)));
document.querySelectorAll('.zoom').forEach(b=>b.addEventListener('click',()=>{{const enlarged=b.closest('.view').querySelector('.drawing').classList.toggle('enlarged');b.setAttribute('aria-pressed',String(enlarged));b.textContent=enlarged?'Fit drawing':'Enlarge drawing';}}));document.getElementById('print').addEventListener('click',()=>window.print());
</script></html>'''
(ROOT/'index.html').write_text(page)
print('Built round-02 review gallery')
